import re


def payload_safety(plaintext):
    unsafe_patterns = [
        r'\b(password|secret|token)\b',
        r'\b(credit card|social security number)\b'
    ]
    for pattern in unsafe_patterns:
        if re.search(pattern, plaintext, re.IGNORECASE):
            return False
    return True

import boto3


def crypto_audit_embedding(ciphertext, audit_note, config=None):
    config = config or {}
    client = boto3.client("kms", region_name=config.get("region"))
    decrypted_text = client.decrypt(CiphertextBlob=ciphertext["ciphertext"])['Plaintext'].decode('utf-8')
    audit_note = f"{audit_note} - Decrypted text: {decrypted_text}"
    return {"audit_note": audit_note}

import boto3


def compliance_note_translate(note, target_language, config=None):
    config = config or {}
    client = boto3.client("translate", region_name=config.get("region"))
    response = client.translate_text(Text=note, SourceLanguageCode="en", TargetLanguageCode=target_language)
    return {"translated_note": response["TranslatedText"]}
